import{_ as e,c as r,o as a,a3 as l}from"./chunks/framework.czLORLkK.js";const g=JSON.parse('{"title":"SyncSeries 제품 소개서 및 도입 제안서 (PDF 다운로드)","description":"SyncSeries 통합 제안서 및 10개 전 제품군(SyncVerse, SyncInsight, SyncLLM, SyncBoot, SyncCMS, SyncShop, SyncOps, SyncETA, SyncCrawl, SyncSDK) 개별 소개서·도입제안서 PDF 다운로드 센터","frontmatter":{"title":"SyncSeries 제품 소개서 및 도입 제안서 (PDF 다운로드)","description":"SyncSeries 통합 제안서 및 10개 전 제품군(SyncVerse, SyncInsight, SyncLLM, SyncBoot, SyncCMS, SyncShop, SyncOps, SyncETA, SyncCrawl, SyncSDK) 개별 소개서·도입제안서 PDF 다운로드 센터","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/proposals/"}]]},"headers":[],"relativePath":"proposals/index.md","filePath":"ko/proposals/index.md","lastUpdated":1792888708000}'),n={name:"proposals/index.md"};function o(s,t,d,i,p,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="제품-소개서-및-도입-제안서-pdf-다운로드" tabindex="-1">제품 소개서 및 도입 제안서 (PDF 다운로드) <a class="header-anchor" href="#제품-소개서-및-도입-제안서-pdf-다운로드" aria-label="Permalink to “제품 소개서 및 도입 제안서 (PDF 다운로드)”">​</a></h1><p>사내 품의, 아키텍처 기술 검토, 차세대 SI/DX 사업 제안에 바로 참고하고 첨부할 수 있는 <strong>SyncSeries 공식 요약 브로셔(4페이지) 및 제품별 도입 제안서(8페이지 A4 표준 규격)</strong> 모음입니다.</p><p>8페이지 도입 제안서는 각 제품의 <strong>도입 배경(현장의 고민) → 해결 방향 → 핵심 기능 &amp; 권장 서버 사양 → 시스템 아키텍처 → 주요 화면 구성 &amp; 작동 시나리오 → 도입 효과(Before/After) → 구축 로드맵 → 기술 사양</strong> 순서로 알기 쉽게 구성되어 있습니다.</p><hr><h2 id="_1-통합-브로셔-및-마스터-도입-제안서" tabindex="-1">1. 통합 브로셔 및 마스터 도입 제안서 <a class="header-anchor" href="#_1-통합-브로셔-및-마스터-도입-제안서" aria-label="Permalink to “1. 통합 브로셔 및 마스터 도입 제안서”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">문서명</th><th style="text-align:left;">대상 독자 및 주요 내용</th><th style="text-align:center;">페이지</th><th style="text-align:center;">다운로드</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SyncSeries 통합 요약 브로셔</strong><br>(<code>SyncSeries_Brochure_v1.0.pdf</code>)</td><td style="text-align:left;"><strong>경영진 · 현업 부서장 · 빠른 개요 파악용</strong><br>• 왜 지금 SyncSeries인가? (현장의 고민과 해결 방식)<br>• 4-Tier 아키텍처 및 10대 제품군 핵심 역할 한눈에 보기<br>• 3단계 운영 안전장치(사전 비교·승인·1-Click 복원) 및 도입 방식</td><td style="text-align:center;">4p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncSeries_Brochure_v1.0.pdf" target="_blank" download="SyncSeries_Brochure_v1.0.pdf">📘 브로셔 다운로드</a></td></tr><tr><td style="text-align:left;"><strong>SyncSeries 통합 도입 제안서</strong><br>(<code>SyncSeries_Master_Proposal.pdf</code>)</td><td style="text-align:left;"><strong>CIO · CTO · PMO · 디지털 전환(DX) 기획팀</strong><br>• 4-Tier 운영 아키텍처 및 표준 MCP/A2A 연동 구조 상세<br>• 10종 전체 에이전트·솔루션 라인업 및 공통 권장 서버 사양<br>• 4단계 점진적 도입 로드맵, Before/After 정량 효과, 거버넌스 체계</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncSeries_Master_Proposal.pdf" target="_blank" download="SyncSeries_Master_Proposal.pdf">📄 제안서 다운로드</a></td></tr></tbody></table><hr><h2 id="_2-오케스트레이션-및-인텔리전스-계층-tier-1-tier-2" tabindex="-1">2. 오케스트레이션 및 인텔리전스 계층 (Tier 1 &amp; Tier 2) <a class="header-anchor" href="#_2-오케스트레이션-및-인텔리전스-계층-tier-1-tier-2" aria-label="Permalink to “2. 오케스트레이션 및 인텔리전스 계층 (Tier 1 &amp; Tier 2)”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">제품명</th><th style="text-align:left;">핵심 역할 및 주요 수록 내용</th><th style="text-align:center;">페이지</th><th style="text-align:center;">다운로드</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SyncVerse</strong><br>(통합 관제 &amp; 오케스트레이터)</td><td style="text-align:left;">• 전사 도메인 에이전트 작업 조율 및 표준 A2A 메시지 브로커<br>• AI SyncOps 5단계 스펙 스튜디오 및 코드 영향도 분석<br>• 단계별 승인(Multi-HITL) 및 SI 4대 산출물 자동 생성</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncVerse_Proposal.pdf" target="_blank" download="SyncVerse_Proposal.pdf">📄 PDF 다운로드</a></td></tr><tr><td style="text-align:left;"><strong>SyncInsight</strong><br>(비즈니스 인텔리전스 &amp; 리서치)</td><td style="text-align:left;">• 사내 DB와 외부 웹 지식을 결합하는 2단계 심층 리서치<br>• 읽기 전용 자연어 SQL 변환(Safe NL2SQL) 및 pgvector 검색<br>• 원인 분석부터 실행 가능한 후속 조치 카드 제안·연동</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncInsight_Proposal.pdf" target="_blank" download="SyncInsight_Proposal.pdf">📄 PDF 다운로드</a></td></tr><tr><td style="text-align:left;"><strong>SyncLLM</strong><br>(중앙 AI 게이트웨이 &amp; FinOps)</td><td style="text-align:left;">• 질문 난이도 기반 멀티 LLM 자동 선택 및 장애 시 자동 우회(Fallback)<br>• Redis 의미 기반 캐싱 및 부서·에이전트별 토큰 예산 관리<br>• 실시간 개인정보(PII) 및 기밀 키워드 입출력 마스킹</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncLLM_Proposal.pdf" target="_blank" download="SyncLLM_Proposal.pdf">📄 PDF 다운로드</a></td></tr></tbody></table><hr><h2 id="_3-도메인-운영-및-엔지니어링-에이전트-tier-3-tier-4" tabindex="-1">3. 도메인 운영 및 엔지니어링 에이전트 (Tier 3 &amp; Tier 4) <a class="header-anchor" href="#_3-도메인-운영-및-엔지니어링-에이전트-tier-3-tier-4" aria-label="Permalink to “3. 도메인 운영 및 엔지니어링 에이전트 (Tier 3 &amp; Tier 4)”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">제품명</th><th style="text-align:left;">핵심 역할 및 주요 수록 내용</th><th style="text-align:center;">페이지</th><th style="text-align:center;">다운로드</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SyncBoot</strong><br>(엔터프라이즈 백오피스 표준)</td><td style="text-align:left;">• Spring Boot 3.5 &amp; Java 25 기반 표준 백오피스 프레임워크<br>• DB 단일 원천(<code>sys_permission</code>) 동적 메뉴 라우팅 및 권한 관리<br>• AES-256 암호화 실시간 환경설정(<code>sys_config</code>) 및 서버 연결 진단</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncBoot_Proposal.pdf" target="_blank" download="SyncBoot_Proposal.pdf">📄 PDF 다운로드</a></td></tr><tr><td style="text-align:left;"><strong>SyncCMS</strong><br>(콘텐츠 자동 발행 &amp; 웹 품질 진단)</td><td style="text-align:left;">• 초안 작성 → SEO 검토 → 발행 3단계 에이전트 협업 워크플로우<br>• 콘텐츠 공백(Gap) 분석 및 데이터 기반 신규 아티클 주제 추천<br>• SEO · AEO · GEO 검색 및 AI 답변 인용 품질 진단</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncCMS_Proposal.pdf" target="_blank" download="SyncCMS_Proposal.pdf">📄 PDF 다운로드</a></td></tr><tr><td style="text-align:left;"><strong>SyncShop</strong><br>(분산 MSA 이커머스 &amp; 프라이싱)</td><td style="text-align:left;">• Gateway, Auth, Admin, Portal, Search 등 8개 독립 마이크로서비스<br>• 최소 마진율 기준을 지키는 다이내믹 프라이싱 일괄 조정<br>• 변경 전 가격 스냅샷 보관 및 1-Click 즉시 복원</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncShop_Proposal.pdf" target="_blank" download="SyncShop_Proposal.pdf">📄 PDF 다운로드</a></td></tr><tr><td style="text-align:left;"><strong>SyncOps</strong><br>(한국형 SI 사업운영 &amp; 손익 관리)</td><td style="text-align:left;">• 발주처 계약단가 vs 실투입원가 비교 실시간 영업이익률 산출<br>• KOSA 기술등급 이력 및 월별 인력 M/M 가동률 히트맵 매트릭스<br>• 4대 보증보험 만기, 하도급법 지급기일 알림, SHA-256 전자연구노트</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncOps_Proposal.pdf" target="_blank" download="SyncOps_Proposal.pdf">📄 PDF 다운로드</a></td></tr><tr><td style="text-align:left;"><strong>SyncETA</strong><br>(자가 치유 E2E 테스트 자동화)</td><td style="text-align:left;">• 마우스 클릭·입력만으로 만드는 노코드 테스트 시나리오 레코딩<br>• 화면 개편 시 문맥과 시각 정보로 셀렉터를 보정하는 AI Self-Healing<br>• 웹(Playwright) · 모바일(Appium) 통합 검증 및 화면 비교</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncETA_Proposal.pdf" target="_blank" download="SyncETA_Proposal.pdf">📄 PDF 다운로드</a></td></tr><tr><td style="text-align:left;"><strong>SyncCrawl</strong><br>(웹 데이터 수집 &amp; RAG 파이프라인)</td><td style="text-align:left;">• 복잡한 셀렉터 작성 없이 스키마 정의로 추출하는 의미 기반 파서<br>• Playwright 클러스터 기반 동적 렌더링 및 광고·메뉴 노이즈 제거<br>• 표·구조 보존 마크다운 변환 및 pgvector 문맥 단위 적재</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncCrawl_Proposal.pdf" target="_blank" download="SyncCrawl_Proposal.pdf">📄 PDF 다운로드</a></td></tr><tr><td style="text-align:left;"><strong>SyncSDK</strong><br>(코딩 보조 &amp; 에이전트 개발 키트)</td><td style="text-align:left;">• 요구사항 분석 → 계획 → 코드 작성 → 4단계 빌드 검증 파이프라인<br>• Spring Boot 애플리케이션을 도메인 에이전트로 연결하는 스타터 키트<br>• 산출물 4종(프로그램 사양서·화면설계서·테이블명세서·단위테스트) 자동 생성</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncSDK_Proposal.pdf" target="_blank" download="SyncSDK_Proposal.pdf">📄 PDF 다운로드</a></td></tr></tbody></table><hr><h2 id="_4-라이브-데모-및-데스크톱-체험-안내" tabindex="-1">4. 라이브 데모 및 데스크톱 체험 안내 <a class="header-anchor" href="#_4-라이브-데모-및-데스크톱-체험-안내" aria-label="Permalink to “4. 라이브 데모 및 데스크톱 체험 안내”">​</a></h2><ul><li><strong>통합 라이브 데모 포털</strong>: <a href="https://sync.empasy.io" target="_blank" rel="noreferrer">https://sync.empasy.io</a> 에서 각 제품의 상세 소개와 관리자·사용자 라이브 데모를 바로 체험하실 수 있습니다.</li><li><strong>SyncETA 데스크톱 앱 다운로드</strong>: <a href="https://empasy.io/ko/download_eta.html" target="_blank" rel="noreferrer">https://empasy.io/ko/download_eta.html</a> 에서 Windows / macOS 설치 파일을 내려받아 로컬에서 바로 테스트 자동화를 실행하실 수 있습니다.</li></ul>',15)])])}const S=e(n,[["render",o]]);export{g as __pageData,S as default};
